const W = 1080, H = 1920;
const EDGE = 1.5;

function insideRings(rings, x, y) {
  let inside = false;
  for (const r of rings) {
    const n = r.length;
    for (let i = 0, j = n - 2; i < n; j = i, i += 2) {
      const xi = r[i], yi = r[i + 1], xj = r[j], yj = r[j + 1];
      if ((yi > y) !== (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi) inside = !inside;
    }
  }
  return inside;
}

/** True when (x, y) is water. */
export function pointInWater(x, y) {
  return insideRings(WATER_RINGS, x, y);
}

// True when the segment from (ax, ay) to (bx, by) runs along the canvas border.
function isBorderSegment(ax, ay, bx, by) {
  return (ax <= EDGE && bx <= EDGE) || (ax >= W - EDGE && bx >= W - EDGE)
    || (ay <= EDGE && by <= EDGE) || (ay >= H - EDGE && by >= H - EDGE);
}

/**
 * Split a ring into its shore runs: open polylines (flat arrays) with the
 * border runs taken out. A ring with no border vertex comes back as one
 * closed run (its first vertex repeated at the end).
 * @param {number[]} ring
 * @returns {number[][]}
 */
export function shoreRuns(ring) {
  const n = ring.length / 2;
  let start = -1;
  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n;
    if (isBorderSegment(ring[2 * i], ring[2 * i + 1], ring[2 * j], ring[2 * j + 1])) { start = j; break; }
  }
  if (start < 0) return [[...ring, ring[0], ring[1]]];
  const runs = [];
  let cur = [ring[2 * start], ring[2 * start + 1]];
  for (let k = 0; k < n; k++) {
    const i = (start + k) % n, j = (i + 1) % n;
    const ax = ring[2 * i], ay = ring[2 * i + 1], bx = ring[2 * j], by = ring[2 * j + 1];
    if (isBorderSegment(ax, ay, bx, by)) {
      if (cur.length >= 4) runs.push(cur);
      cur = [bx, by];
    } else {
      cur.push(bx, by);
    }
  }
  if (cur.length >= 4) runs.push(cur);
  return runs;
}

/**
 * Where a route polyline crosses water. Walks the line every `step` px.
 * @param {Array<[number, number]|{x:number,y:number}>} pts the polyline (a
 *   measured road piece's poly, so the distances match the piece's own)
 * @param {number} [step=1]
 * @returns {{total: number, spans: Array<{start:[number,number], end:[number,number], s0:number, s1:number, length:number}>}}
 *   s0 and s1 are distances along the line from its first point.
 */
export function waterSpans(pts, step = 1) {
  const P = pts.map(p => Array.isArray(p) ? p : [p.x, p.y]);
  const spans = [];
  let s = 0, open = null, last = null;
  for (let k = 0; k < P.length - 1; k++) {
    const [ax, ay] = P[k], [bx, by] = P[k + 1];
    const L = Math.hypot(bx - ax, by - ay);
    const n = Math.max(1, Math.ceil(L / step));
    for (let i = (k === 0 ? 0 : 1); i <= n; i++) {
      const t = i / n, x = ax + (bx - ax) * t, y = ay + (by - ay) * t, d = s + L * t;
      const wet = pointInWater(x, y);
      if (wet && !open) open = { start: [x, y], s0: d };
      if (!wet && open) {
        spans.push({ ...open, end: last.p, s1: last.d, length: last.d - open.s0 });
        open = null;
      }
      last = { p: [x, y], d };
    }
    s += L;
  }
  if (open) spans.push({ ...open, end: last.p, s1: last.d, length: last.d - open.s0 });
  for (const sp of spans) {
    sp.start = sp.start.map(v => Math.round(v * 10) / 10);
    sp.end = sp.end.map(v => Math.round(v * 10) / 10);
    sp.s0 = Math.round(sp.s0 * 10) / 10; sp.s1 = Math.round(sp.s1 * 10) / 10;
    sp.length = Math.round(sp.length * 10) / 10;
  }
  return { total: Math.round(s * 10) / 10, spans };
}

/**
 * Share of a disc that is water, sampled on a grid.
 * @param {number} cx
 * @param {number} cy
 * @param {number} r
 * @param {number} [step=2]
 * @returns {number} 0 to 1
 */
export function discWetness(cx, cy, r, step = 2) {
  let n = 0, wet = 0;
  for (let y = cy - r + step / 2; y < cy + r; y += step) {
    for (let x = cx - r + step / 2; x < cx + r; x += step) {
      if ((x - cx) ** 2 + (y - cy) ** 2 > r * r) continue;
      n++;
      if (pointInWater(x, y)) wet++;
    }
  }
  return n ? wet / n : 0;
}
